    private function relation(string$type):array{$public=$type==='organization'?str_repeat('a',32):str_repeat('b',32);$state=$this->pdo->prepare('SELECT projection_sha256 FROM api_v2_directory_resource_state WHERE resource_type=?');$state->execute([$type]);return['externalId'=>$type==='organization'?'org-ext':'client-ext','expectedPublicId'=>$public,'expectedRevision'=>'1','expectedProjectionSha256'=>$state->fetchColumn()];}
    private function portalState():array{return['workspace'=>$this->pdo->query('SELECT * FROM portal_v2_workspaces ORDER BY id')->fetchAll(PDO::FETCH_ASSOC),'projection'=>$this->pdo->query('SELECT * FROM portal_projection_state ORDER BY integration_profile_id,workspace_public_id')->fetchAll(PDO::FETCH_ASSOC),'outbox'=>$this->pdo->query('SELECT * FROM portal_projection_outbox ORDER BY id')->fetchAll(PDO::FETCH_ASSOC)];}
    private function assertPortalUnchanged(array$before):void{self::assertSame($before,$this->portalState(),'Project synchronization must be portal/delivery neutral.');}
    public function testCreateUpdateNoOpBindAndRefreshNeverProjectOrDeliver():void
    {
        $portal=$this->portalState();$create=['commandId'=>'423e4567-e89b-42d3-a456-426614174000','externalId'=>'project-ext','expectedAuthorizationGeneration'=>'0','project'=>['name'=>'Shared name','description'=>'Safe scope','estimatedStart'=>'2026-09-01','estimatedEnd'=>'2026-09-30'],'organization'=>$this->relation('organization'),'client'=>$this->relation('client')];
        $out=api_v2_project_sync_write($this->pdo,'create',$create,7,$this->headers,'r1');self::assertSame(201,$out['status']);self::assertSame('1',$out['payload']['result']['authorizationGeneration']);self::assertSame(['portalPublished'=>false,'publicLinkEnabled'=>false],$out['payload']['result']['presentation']);self::assertSame(1,(int)$this->pdo->query('SELECT COUNT(*) FROM schedule_entries')->fetchColumn());self::assertNull($this->pdo->query('SELECT created_by FROM schedule_entries')->fetchColumn());self::assertSame(1,(int)$this->pdo->query('SELECT revision FROM projects')->fetchColumn());$createVersion=(string)$this->pdo->query('SELECT source_version FROM projects')->fetchColumn();self::assertMatchesRegularExpression('/^v-[0-9a-f]{32}$/',$createVersion);$this->assertPortalUnchanged($portal);
        self::assertTrue(api_v2_project_sync_write($this->pdo,'create',$create,7,$this->headers,'r2')['payload']['replayed']);$this->assertPortalUnchanged($portal);$changed=$create;$changed['project']['name']='Other';self::assertSame(409,api_v2_project_sync_write($this->pdo,'create',$changed,7,$this->headers,'r3')['status']);
        $resource=$out['payload']['result']['resource'];$update=['commandId'=>'523e4567-e89b-42d3-a456-426614174000','externalId'=>'project-ext','expectedRevision'=>$resource['revision'],'expectedProjectionSha256'=>$resource['projectionSha256'],'expectedAuthorizationGeneration'=>'1','project'=>['name'=>'Shared name','description'=>'Updated','estimatedStart'=>'2026-09-01','estimatedEnd'=>'2026-10-01']];$updated=api_v2_project_sync_write($this->pdo,'update',$update,7,$this->headers,'r4');self::assertSame('2',$updated['payload']['result']['resource']['revision']);$updateVersion=(string)$this->pdo->query('SELECT source_version FROM projects')->fetchColumn();self::assertNotSame($createVersion,$updateVersion);$this->assertPortalUnchanged($portal);
        $unchanged=$update;$unchanged['commandId']='533e4567-e89b-42d3-a456-426614174000';$unchanged['expectedRevision']='2';$unchanged['expectedProjectionSha256']=$updated['payload']['result']['resource']['projectionSha256'];$noOp=api_v2_project_sync_write($this->pdo,'update',$unchanged,7,$this->headers,'r5');self::assertSame('2',$noOp['payload']['result']['resource']['revision']);self::assertSame($updateVersion,$this->pdo->query('SELECT source_version FROM projects')->fetchColumn());self::assertSame(2,(int)$this->pdo->query('SELECT COUNT(*) FROM project_changes')->fetchColumn());$this->assertPortalUnchanged($portal);
        $this->pdo->exec("INSERT INTO projects(public_id,organization_id,name,status,portal_publish_enabled,public_project_enabled,revision,source_version,invoice_billing_period,project_invoice_auto_email) VALUES('cccccccccccccccccccccccccccccccc',10,'Browser project','not_started',1,0,1,'browser-v1','per_invoice',0)");$browserId=(int)$this->pdo->lastInsertId();$this->pdo->beginTransaction();$browser=(new ProjectRevisionService($this->pdo))->initialize($browserId,'baseline');$this->pdo->commit();$bind=['commandId'=>'543e4567-e89b-42d3-a456-426614174000','externalId'=>'browser-project-ext','expectedPublicId'=>str_repeat('c',32),'expectedRevision'=>'1','expectedProjectionSha256'=>ProjectRevisionService::projectionHash($browser),'expectedAuthorizationGeneration'=>'1'];$bound=api_v2_project_sync_write($this->pdo,'bind',$bind,7,$this->headers,'r6');self::assertSame(200,$bound['status']);self::assertSame('2',$bound['payload']['result']['authorizationGeneration']);$this->assertPortalUnchanged($portal);
        $inventory=api_v2_project_inventory_read($this->pdo,null,10,7,$this->headers,'r7');self::assertCount(2,$inventory['projects']);self::assertArrayNotHasKey('budget',$inventory['projects'][0]);$id=(int)$this->pdo->query("SELECT id FROM projects WHERE public_id='".$resource['publicId']."'")->fetchColumn();$this->pdo->beginTransaction();$this->pdo->exec("UPDATE projects SET name='Browser edit' WHERE id=$id");$live=(new ProjectRevisionService($this->pdo))->advance($id,'update');$this->pdo->commit();self::assertSame(409,api_v2_project_binding_status_read($this->pdo,'project-ext',7,$this->headers,'r8')['status']);
        $hash=ProjectRevisionService::projectionHash($live);$refresh=['commandId'=>'623e4567-e89b-42d3-a456-426614174000','externalId'=>'project-ext','expectedPublicId'=>$resource['publicId'],'expectedPriorRevision'=>'2','expectedRevision'=>'3','expectedProjectionSha256'=>$hash,'expectedAuthorizationGeneration'=>'2'];$refreshed=api_v2_project_sync_write($this->pdo,'refresh',$refresh,7,$this->headers,'r9');self::assertSame('3',$refreshed['payload']['result']['authorizationGeneration']);self::assertSame(200,api_v2_project_binding_status_read($this->pdo,'project-ext',7,$this->headers,'r10')['status']);$this->assertPortalUnchanged($portal);
    }
    public function testReleaseAttestationFailsClosedAndReceiptGoesStale():void
    {
        $initial=api_v2_project_backfill_attestation($this->pdo);self::assertFalse($initial['complete']);self::assertSame(0,$initial['violations']['index']);self::assertSame(0,$initial['violations']['foreign_key']);$digest=api_v2_project_backfill_attestation_persist($this->pdo);self::assertTrue(api_v2_project_backfill_attestation_receipt_is_current($this->pdo,$digest));self::assertTrue(api_v2_project_backfill_attestation($this->pdo)['complete']);$this->pdo->exec("UPDATE schema_migrations SET filename='wrong.sql' WHERE version=102");$bad=api_v2_project_backfill_attestation($this->pdo);self::assertFalse($bad['schemaReady']);self::assertFalse($bad['complete']);$this->pdo->exec("UPDATE schema_migrations SET filename='0102_api_v2_project_synchronization.sql' WHERE version=102");$this->pdo->exec('DELETE FROM api_v2_project_authorization_state');$missingAuth=api_v2_project_backfill_attestation($this->pdo);self::assertGreaterThan(0,$missingAuth['violations']['authorization']);self::assertFalse($missingAuth['complete']);$this->pdo->exec('INSERT INTO api_v2_project_authorization_state(application_pk,authorization_generation) VALUES(3,0)');$this->pdo->exec("UPDATE schema_migrations SET checksum='".str_repeat('0',64)."' WHERE version=102");self::assertFalse(api_v2_project_backfill_attestation_receipt_is_current($this->pdo,$digest));$this->pdo->exec('DROP TABLE api_v2_project_command_receipts');$partial=api_v2_project_backfill_attestation($this->pdo);self::assertGreaterThan(0,$partial['violations']['schema']);self::assertFalse($partial['complete']);
    }
    public function testMigrationChecksumAcceptsRawLfAndCrLf():void
    {
        $path=tempnam(sys_get_temp_dir(),'pa-release-');self::assertNotFalse($path);try{file_put_contents($path,"one\r\ntwo\r\n");$accepted=api_v2_project_release_file_accepted_digests($path);self::assertContains(hash('sha256',"one\r\ntwo\r\n"),$accepted);self::assertContains(hash('sha256',"one\ntwo\n"),$accepted);self::assertSame(hash('sha256',"one\ntwo\n"),api_v2_project_release_file_digest($path));}finally{@unlink($path);}
    }
