    {
        self::assertNull(api_v2_project_sync_command_parse('bind','{}'));$root=dirname(__DIR__,2);$router=file_get_contents($root.'/public/index.php');self::assertStringContainsString('APP_API_V2_PROJECTS_BINDING_REFRESH_ENABLED',$router);self::assertStringContainsString('APP_API_V2_PROJECTS_CREATE_ENABLED=false',file_get_contents($root.'/config/.env.example'));require_once $root.'/src/utils/api_scopes.php';foreach(['projects.create','projects.write','projects.bind','projects.binding.revision.refresh','projects.binding_status.read','projects.inventory.read']as$scope)self::assertFalse(api_key_has_scope('full',$scope,false));
    }
